"""Analyze datasets generated by ``fqi/lunarlander/run.py``."""

import argparse
import pathlib
import pickle
import re

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np


DATASET_PATTERN = re.compile(
    r"dataset_task_(\d+)_wind_power_([-+0-9.eE]+)_seed_(\d+)\.pkl"
)
STATE_NAMES = (
    "x position",
    "y position",
    "x velocity",
    "y velocity",
    "angle",
    "angular velocity",
    "left leg contact",
    "right leg contact",
)


def parse_dataset(dataset):
    states = np.asarray([transition[0] for transition in dataset])
    actions = np.asarray([transition[1] for transition in dataset]).reshape(-1)
    rewards = np.asarray([transition[2] for transition in dataset])
    absorbing = np.asarray([transition[4] for transition in dataset])
    last = np.asarray([transition[5] for transition in dataset], dtype=bool)
    return states, actions, rewards, absorbing, last


def episode_statistics(rewards, last):
    end_indices = np.flatnonzero(last)
    if len(end_indices) == 0:
        return np.array([], dtype=int), np.array([], dtype=float)

    lengths = np.diff(end_indices, prepend=-1)
    starts = np.r_[0, end_indices[:-1] + 1]
    returns = np.asarray([
        rewards[start:end + 1].sum()
        for start, end in zip(starts, end_indices)
    ])
    return lengths, returns


def load_groups(data_dir, max_points_per_file=5000):
    groups = {}
    paths = sorted(data_dir.glob("dataset_task_*_wind_power_*_seed_*.pkl"))
    if not paths:
        raise FileNotFoundError(f"No LunarLander dataset found in {data_dir}")

    for path in paths:
        match = DATASET_PATTERN.fullmatch(path.name)
        if match is None:
            continue
        task_idx, wind_power, seed = match.groups()
        key = (int(task_idx), float(wind_power))
        group = groups.setdefault(key, {
            "seeds": [], "transitions": 0, "episodes": 0,
            "positive": 0, "negative": 0, "zero": 0, "absorbing": 0,
            "actions": np.zeros(4, dtype=int),
            "state_min": np.full(8, np.inf),
            "state_max": np.full(8, -np.inf),
            "lengths": [], "returns": [], "states_sample": [],
            "rewards_sample": [],
        })

        with path.open("rb") as stream:
            dataset = pickle.load(stream)
        states, actions, rewards, absorbing, last = parse_dataset(dataset)
        lengths, episode_returns = episode_statistics(rewards, last)

        group["seeds"].append(int(seed))
        group["transitions"] += len(dataset)
        group["episodes"] += len(lengths)
        group["positive"] += int(np.sum(rewards > 0))
        group["negative"] += int(np.sum(rewards < 0))
        group["zero"] += int(np.sum(rewards == 0))
        group["absorbing"] += int(np.sum(absorbing))
        group["actions"] += np.bincount(actions.astype(int), minlength=4)[:4]
        group["state_min"] = np.minimum(group["state_min"], states.min(axis=0))
        group["state_max"] = np.maximum(group["state_max"], states.max(axis=0))
        group["lengths"].append(lengths)
        group["returns"].append(episode_returns)

        sample_size = min(max_points_per_file, len(states))
        sample_idx = np.linspace(0, len(states) - 1, sample_size, dtype=int)
        group["states_sample"].append(states[sample_idx])
        group["rewards_sample"].append(rewards[sample_idx])

    for group in groups.values():
        group["lengths"] = np.concatenate(group["lengths"])
        group["returns"] = np.concatenate(group["returns"])
        group["states_sample"] = np.concatenate(group["states_sample"])
        group["rewards_sample"] = np.concatenate(group["rewards_sample"])
        group["seeds"].sort()
    return groups


def write_report(groups, output_dir):
    lines = ["=" * 72, "LunarLander dataset analysis"]
    for (task_idx, wind_power), group in sorted(groups.items()):
        n = group["transitions"]
        lengths = group["lengths"]
        returns = group["returns"]
        lines.extend([
            "",
            f"Task {task_idx} - wind_power={wind_power:g}",
            f"  Seeds                 : {group['seeds']}",
            f"  Total transitions     : {n}",
            f"  Episodes              : {group['episodes']}",
            f"  Episode length        : mean={lengths.mean():.1f}  min={lengths.min()}  max={lengths.max()}",
            f"  Episode return        : mean={returns.mean():.2f}  min={returns.min():.2f}  max={returns.max():.2f}",
            f"  Positive rewards      : {group['positive']} ({100 * group['positive'] / n:.2f}%)",
            f"  Negative rewards      : {group['negative']} ({100 * group['negative'] / n:.2f}%)",
            f"  Zero rewards          : {group['zero']} ({100 * group['zero'] / n:.2f}%)",
            f"  Absorbing states      : {group['absorbing']}",
            f"  Actions 0/1/2/3       : {' / '.join(map(str, group['actions']))}",
        ])
        for index, name in enumerate(STATE_NAMES):
            lines.append(
                f"  State[{index}] {name:<18}: "
                f"[{group['state_min'][index]:.3f}, {group['state_max'][index]:.3f}]"
            )
    lines.append("=" * 72)

    report = "\n".join(lines) + "\n"
    (output_dir / "dataset_analysis.txt").write_text(report, encoding="utf-8")
    print(report)


def plot_groups(groups, output_dir):
    ordered_groups = sorted(groups.items())
    figure, axes = plt.subplots(
        len(ordered_groups), 3,
        figsize=(15, 4 * len(ordered_groups)),
        squeeze=False,
    )
    figure.suptitle("LunarLander datasets", fontsize=14)

    for row, ((task_idx, wind_power), group) in enumerate(ordered_groups):
        label = f"task {task_idx}, wind={wind_power:g}"
        states = group["states_sample"]
        rewards = group["rewards_sample"]

        scatter = axes[row, 0].scatter(
            states[:, 0], states[:, 1], c=rewards, cmap="RdYlGn",
            s=2, alpha=0.35,
        )
        figure.colorbar(scatter, ax=axes[row, 0], shrink=0.8, label="reward")
        axes[row, 0].set(xlabel="x position", ylabel="y position",
                         title=f"{label} - state coverage")

        axes[row, 1].hist(rewards, bins=50, color="tab:blue")
        axes[row, 1].set(xlabel="reward", ylabel="sampled transitions",
                         title=f"{label} - rewards")

        axes[row, 2].hist(group["lengths"], bins=30, color="tab:orange")
        axes[row, 2].set(xlabel="episode length", ylabel="episodes",
                         title=f"{label} - lengths")

    figure.tight_layout(rect=(0, 0, 1, 0.98))
    figure.savefig(output_dir / "dataset_analysis.png", dpi=150,
                   bbox_inches="tight")
    plt.close(figure)


def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--data-dir", type=pathlib.Path, required=True,
        help="Directory containing dataset_task_*_wind_power_*_seed_*.pkl",
    )
    parser.add_argument(
        "--output-dir", type=pathlib.Path, default=None,
        help="Output directory (default: DATA_DIR/analysis)",
    )
    parser.add_argument("--max-points-per-file", type=int, default=5000)
    return parser.parse_args()


if __name__ == "__main__":
    args = parse_args()
    output_dir = args.output_dir or args.data_dir / "analysis"
    output_dir.mkdir(parents=True, exist_ok=True)
    dataset_groups = load_groups(args.data_dir, args.max_points_per_file)
    write_report(dataset_groups, output_dir)
    plot_groups(dataset_groups, output_dir)
    print(f"Saved analysis to {output_dir}")
